/**
 * Verifies that the version metadata of every add-on is internally
 * consistent, i.e. that the files generated by .github/scripts/addon-update.js
 * (config.yaml version, build.yaml build_from, Dockerfile ARGs) match what
 * the templates in addon_info.yaml would currently render.
 *
 * Run: node .github/scripts/tests/test-addon-consistency.js
 *
 * Checked per add-on (strict: missing/malformed sections fail):
 *   1. source.version_template is a "regex:" template and
 *      source.current_version matches it
 *   2. config.yaml "version" equals the rendered config.version_template
 *      (formatVersion of source.current_version with app_build = config.build)
 *   3. build.yaml build_from entries match info.build (image + rendered
 *      version, with {{arch}} substitution) for every arch in config.arch
 *   4. Dockerfile ARG BUILD_FROM matches the rendered build_from image and an
 *      inline ARG BUILD_VERSION matches config.yaml's version (no-default
 *      ARG BUILD_VERSION declarations are legitimate and skipped)
 *
 * CHANGELOG.md is deliberately not verified: its content is a fetched
 * release body, only the "# <version>" fallback header is generated.
 */

'use strict';

const fs = require('fs');
const path = require('path');

let yaml;
try {
  yaml = require('yaml');
} catch {
  const { execSync } = require('child_process');
  execSync('npm install yaml', { stdio: 'inherit' });
  yaml = require('yaml');
}

const { formatVersion } = require('../version-format');

const ROOT = path.resolve(__dirname, '..', '..', '..');

let checks = 0;
let failures = 0;

function fail(msg) {
  failures++;
  console.error(`  FAIL ${msg}`);
}

function ok(msg) {
  checks++;
  console.log(`  ok   ${msg}`);
}

/** Mirrors addon-update.js shellUnquote-free ARG value stripping. */
function unquote(value) {
  const trimmed = value.trim();
  if (
    (trimmed.startsWith('"') && trimmed.endsWith('"') && trimmed.length >= 2) ||
    (trimmed.startsWith("'") && trimmed.endsWith("'") && trimmed.length >= 2)
  ) {
    return trimmed.slice(1, -1);
  }
  return trimmed;
}

/** Mirrors addon-update.js replaceArchPlaceholder. */
function replaceArchPlaceholder(value, arch) {
  return value.replaceAll('{{arch}}', arch).replaceAll('{arch}', arch);
}

function readYamlFile(file) {
  return yaml.parse(fs.readFileSync(file, 'utf8'));
}

function discoverAddons() {
  return fs
    .readdirSync(ROOT, { withFileTypes: true })
    .filter((e) => e.isDirectory())
    .map((e) => e.name)
    .filter((name) => fs.existsSync(path.join(ROOT, name, 'addon_info.yaml')))
    .sort();
}

/**
 * Renders a version template exactly like addon-update.js does, returning
 * { error } instead of throwing so the test can report per-addon failures.
 */
function renderVersion(addon, info, template, extra = {}) {
  const source = path.join(addon, 'addon_info.yaml');
  let regex;
  try {
    regex = new RegExp(info.source.version_template.slice('regex:'.length));
  } catch (e) {
    return { error: `version_template does not compile: ${e.message}` };
  }
  try {
    return {
      value: formatVersion(info.source.current_version, regex, template, {
        ...extra,
        app_build: extra.app_build ?? info.config?.build,
      }),
    };
  } catch (e) {
    return { error: `failed to render ${JSON.stringify(template)}: ${e.message}` };
  }
}

function checkSourceTemplate(addon, info) {
  if (!info.source) {
    fail(`${addon}: missing "source" section`);
    return null;
  }
  if (!info.source.current_version) {
    fail(`${addon}: missing "source.current_version"`);
    return null;
  }
  const template = info.source.version_template;
  if (!template) {
    fail(`${addon}: missing "source.version_template"`);
    return null;
  }
  if (!template.startsWith('regex:')) {
    fail(`${addon}: source.version_template ${JSON.stringify(template)} does not start with "regex:"`);
    return null;
  }
  let regex;
  try {
    regex = new RegExp(template.slice('regex:'.length));
  } catch (e) {
    fail(`${addon}: source.version_template does not compile: ${e.message}`);
    return null;
  }
  if (!regex.test(info.source.current_version)) {
    fail(
      `${addon}: source.current_version "${info.source.current_version}" does not match source.version_template ${JSON.stringify(template)}`
    );
    return null;
  }
  ok(`${addon}: current_version "${info.source.current_version}" matches source.version_template`);
  return regex;
}

function checkConfigVersion(addon, info, config, sourceRegex) {
  if (!info.config) {
    fail(`${addon}: missing "config" section`);
    return;
  }
  const template = info.config.version_template;
  if (!template) {
    fail(`${addon}: missing "config.version_template"`);
    return;
  }
  if (template.includes('{{app_build}}') && info.config.build == null) {
    fail(`${addon}: config.version_template uses {{app_build}} but "config.build" is missing`);
    return;
  }
  const result = renderVersion(addon, info, template);
  if (result.error) {
    fail(`${addon}: ${result.error}`);
    return;
  }
  if (result.value == null) {
    fail(`${addon}: config.version_template rendered to null`);
    return;
  }
  if (String(config.version) !== result.value) {
    fail(
      `${addon}: config.yaml version "${config.version}" != rendered config.version_template "${result.value}"`
    );
    return;
  }
  ok(`${addon}: config.yaml version "${config.version}" matches config.version_template`);
}

function checkBuildYaml(addon, info, config) {
  const buildFile = path.join(addon, 'build.yaml');
  if (!fs.existsSync(buildFile)) {
    fail(`${addon}: "build" section present but build.yaml is missing`);
    return null;
  }
  let build;
  try {
    build = readYamlFile(buildFile);
  } catch (e) {
    fail(`${addon}: failed to parse build.yaml: ${e.message}`);
    return null;
  }
  if (!Array.isArray(config.arch) || config.arch.length === 0) {
    fail(`${addon}: config.arch must be a non-empty list when a build section is present`);
    return null;
  }

  const buildImage = info.build?.image ?? info.source.image;
  if (!buildImage) {
    fail(`${addon}: neither build.image nor source.image is defined`);
    return null;
  }
  let buildVersion = null;
  if (info.build?.version_template != null) {
    const result = renderVersion(addon, info, info.build.version_template);
    if (result.error) {
      fail(`${addon}: ${result.error}`);
      return null;
    }
    buildVersion = result.value;
  }
  const buildFromImage = `${buildImage}${buildVersion != null ? `:${buildVersion}` : ''}`;

  for (const arch of config.arch) {
    const expected = replaceArchPlaceholder(buildFromImage, arch);
    const actual = build.build_from?.[arch];
    if (actual !== expected) {
      fail(`${addon}: build.yaml build_from.${arch} "${actual}" != expected "${expected}"`);
    } else {
      ok(`${addon}: build.yaml build_from.${arch} "${actual}"`);
    }
  }
  return buildFromImage;
}

function checkDockerfile(addon, info, config, buildFromImage) {
  const dockerfile = path.join(addon, 'Dockerfile');
  if (!fs.existsSync(dockerfile)) {
    fail(`${addon}: "build" section present but Dockerfile is missing`);
    return;
  }
  const content = fs.readFileSync(dockerfile, 'utf8');

  const fromMatch = /^ARG BUILD_FROM=(.+)$/m.exec(content);
  const expectedFrom = replaceArchPlaceholder(buildFromImage, 'amd64');
  if (!fromMatch) {
    fail(`${addon}: Dockerfile is missing an "ARG BUILD_FROM=" line`);
  } else if (unquote(fromMatch[1]) !== expectedFrom) {
    fail(`${addon}: Dockerfile ARG BUILD_FROM "${unquote(fromMatch[1])}" != expected "${expectedFrom}"`);
  } else {
    ok(`${addon}: Dockerfile ARG BUILD_FROM matches`);
  }

  const versionMatch = /^ARG BUILD_VERSION=(.+)$/m.exec(content);
  if (versionMatch) {
    const actual = unquote(versionMatch[1]);
    if (actual !== String(config.version)) {
      fail(`${addon}: Dockerfile ARG BUILD_VERSION "${actual}" != config.yaml version "${config.version}"`);
    } else {
      ok(`${addon}: Dockerfile ARG BUILD_VERSION matches config.yaml version`);
    }
  }
}

function checkAddon(addon) {
  let info;
  let config;
  try {
    info = readYamlFile(path.join(addon, 'addon_info.yaml'));
    config = readYamlFile(path.join(addon, 'config.yaml'));
  } catch (e) {
    fail(`${addon}: failed to parse YAML: ${e.message}`);
    return;
  }

  const sourceRegex = checkSourceTemplate(addon, info);
  if (!sourceRegex) return;

  checkConfigVersion(addon, info, config, sourceRegex);

  const buildEnabled = info.build != null && (info.build?.enabled ?? true);
  if (!buildEnabled) return;

  const buildFromImage = checkBuildYaml(addon, info, config);
  if (buildFromImage == null) return;

  checkDockerfile(addon, info, config, buildFromImage);
}

function main() {
  const addons = discoverAddons();
  if (addons.length === 0) {
    console.error('No add-on directories (with an addon_info.yaml) found');
    process.exit(1);
  }
  console.log(`Checking ${addons.length} add-ons for version consistency\n`);
  for (const addon of addons) {
    checkAddon(addon);
  }
  console.log(`\n${checks} passed, ${failures} failed`);
  if (failures > 0) process.exit(1);
}

main();
